import ExpoModulesCore
import Speech

public class ExpoSpeechModule: Module {
  private var recognitionTask: SFSpeechRecognitionTask?

  public func definition() -> ModuleDefinition {
    Name("ExpoSpeech")

    Events("onPartialResult", "onFinalResult", "onTranscriptionError")

    Function("getAuthorizationStatus") { () -> String in
      Self.statusString(for: SFSpeechRecognizer.authorizationStatus())
    }

    AsyncFunction("requestAuthorization") { (promise: Promise) in
      SFSpeechRecognizer.requestAuthorization { status in
        promise.resolve(Self.statusString(for: status))
      }
    }

    Function("startTranscription") {
      self.recognitionTask?.cancel()
      self.recognitionTask = nil

      guard let recognizer = SFSpeechRecognizer(locale: Locale(identifier: "en-US")), recognizer.isAvailable else {
        self.sendEvent("onTranscriptionError", ["message": "Speech recognizer is unavailable"])
        return
      }
      guard let fileURL = Bundle.main.url(forResource: "sample", withExtension: "wav") else {
        self.sendEvent("onTranscriptionError", ["message": "Bundled sample audio file was not found"])
        return
      }

      let request = SFSpeechURLRecognitionRequest(url: fileURL)
      request.shouldReportPartialResults = true

      self.recognitionTask = recognizer.recognitionTask(with: request) { result, error in
        if let error = error {
          self.sendEvent("onTranscriptionError", ["message": error.localizedDescription])
          self.recognitionTask = nil
          return
        }
        guard let result = result else { return }
        let text = result.bestTranscription.formattedString
        if result.isFinal {
          self.sendEvent("onFinalResult", ["text": text])
          self.recognitionTask = nil
        } else {
          self.sendEvent("onPartialResult", ["text": text])
        }
      }
    }
  }

  private static func statusString(for status: SFSpeechRecognizerAuthorizationStatus) -> String {
    switch status {
    case .authorized:
      return "authorized"
    case .denied, .restricted:
      return "denied"
    case .notDetermined:
      return "notDetermined"
    @unknown default:
      return "notDetermined"
    }
  }
}

